/**
 * Cloudflare Worker entry: the OpenNext build handles requests. Two cron triggers run alongside:
 * the daily demo reset, and a weekday job (stale PRs and standup digests) that runs inside the
 * Next.js app so it shares the app's code and stays within the free plan's Worker size.
 */
import type { ExecutionContext, ScheduledController } from "@cloudflare/workers-types";
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
import handler from "./.open-next/worker.js";
import { resetDemoDatabase } from "./src/server/demo/reset";

const DAILY_JOBS_CRON = "0 8 * * 1-5";

declare global {
  var __agilePulseCronToken: string | undefined;
}

async function runDailyJobs(env: CloudflareEnv, ctx: ExecutionContext) {
  const token = crypto.randomUUID();
  globalThis.__agilePulseCronToken = token;
  try {
    const site = (env as unknown as { SITE_URL?: string }).SITE_URL ?? "http://localhost";
    const request = new Request(new URL("/api/cron/daily", site), { method: "POST", headers: { "x-agile-pulse-cron": token } });
    const response = (await (handler as ExportedHandler).fetch(request, env, ctx)) as Response;
    console.log(`Daily jobs: ${response.status} ${await response.text()}`);
  } finally {
    globalThis.__agilePulseCronToken = undefined;
  }
}

export default {
  fetch: (handler as ExportedHandler).fetch,
  async scheduled(controller: ScheduledController, env: CloudflareEnv, ctx: ExecutionContext) {
    if (controller.cron === DAILY_JOBS_CRON) {
      ctx.waitUntil(runDailyJobs(env, ctx));
      return;
    }
    ctx.waitUntil(resetDemoDatabase(env.DB).then((count) => console.log(count ? `Demo reset: ${count} tables restored` : "Demo reset skipped: nothing changed")));
  },
};

type ExportedHandler = { fetch: (...args: unknown[]) => Promise<unknown> };
